module.exports=[92046,a=>{"use strict";let b={id:"misi-penjelajah-pancasila",version:1,title:"Misi Penjelajah Pancasila",mapel:"PPKn",kelas:"VII",themeId:"hakikat-norma",navbar:{logoText:"⛵ Misi Penjelajah Pancasila",logoColor:"y",progressGradient:["y","c"]},screens:[{id:"s-cover",templateType:"cover",background:{type:"radial",color1:"y",color2:"bg"},blocks:[{type:"cover",icon:"🇮🇩",title:"Makna dan Nilai yang Terkandung dalam Pancasila",subtitle:"Bab 1 — Pertemuan 2",badges:[{icon:"📝",text:"TP-2 Menguraikan",color:"r"},{icon:"🔍",text:"TP-3 Mengidentifikasi",color:"c"},{icon:"⚖️",text:"TP-4 Membedakan",color:"p"},{icon:"🎮",text:"5 Misi Interaktif",color:"g"}],meta:{durasi:"80 Menit",fase:"Fase D",elemen:"Pancasila"},cta:{label:"⛵ Mulai Penjelajahan!",action:"s-petunjuk"},background:{type:"gradient",color1:"y",color2:"bg"}}],nav:{next:"s-petunjuk",nextLabel:"Surat Misi"}},{id:"s-petunjuk",templateType:"petunjuk",sectionLabel:"📜 Surat Misi",sectionColor:"y",blocks:[{type:"petunjuk",title:"Surat Misi",titleHighlight:"Penjelajah",items:[{icon:"🗺️",title:"Jelajahi 5 Pulau",body:"Baca materi setiap sila Pancasila dalam 4 tab + uraikan dengan kata-katamu sendiri (Tab 5)"},{icon:"⚔️",title:"Hadapi Tantangan",body:"Hotspot, Drag & Drop, Studi Kasus + jelaskan alasanmu setelah tantangan!"},{icon:"🏔️",title:"Pendakian & Perkemahan",body:"5 soal evaluasi akhir + diskusi kelompok & refleksi individu di akhir perjalanan"}],tips:"💡 Ikuti alur dari awal sampai akhir. Setiap misi punya materi + tantangan. Jawaban diskusimu tersimpan sebagai portofolio!",tipsColor:"y"}],nav:{prev:"s-cover",next:"s-tp",nextLabel:"Bekal Penjelajah"}},{id:"s-tp",templateType:"tp",sectionLabel:"🎒 Bekal Penjelajah",sectionColor:"y",blocks:[{type:"tp",title:"Yang Akan Kamu",titleHighlight:"Kuasai Hari Ini",items:[{num:1,verb:"Menguraikan",desc:"makna dan nilai yang terkandung dalam setiap sila Pancasila secara mendalam",color:"r"},{num:2,verb:"Mengidentifikasi",desc:"penerapan nilai-nilai Pancasila dalam kehidupan sehari-hari di lingkungan sekolah dan masyarakat",color:"c"},{num:3,verb:"Membedakan",desc:"perilaku yang sesuai dan tidak sesuai dengan nilai-nilai Pancasila dengan memberikan alasan",color:"p"}],profil:"🔗 Profil Pelajar Pancasila: Beriman & Bertakwa · Berkebhinekaan Global · Gotong Royong · Bernalar Kritis",profilColor:"g"},{type:"alur",title:"⏱️ Alur Kegiatan 80 Menit",totalDurasi:"80",steps:[{dot:"y",durasi:"5'",judul:"Pengantar",deskripsi:"Menjembatani Pertemuan 1 → Pertemuan 2"},{dot:"r",durasi:"10'",judul:"Pemantik",deskripsi:"Pertanyaan pemantik + persiapan bekal misi"},{dot:"p",durasi:"5'",judul:"Tujuan",deskripsi:"Orientasi tujuan & alur misi penjelajahan"},{dot:"c",durasi:"35'",judul:"Eksplorasi",deskripsi:"Jelajahi 5 misi materi & tantangan interaktif"},{dot:"o",durasi:"15'",judul:"Evaluasi",deskripsi:"5 soal pilihan ganda evaluasi akhir"},{dot:"g",durasi:"10'",judul:"Refleksi",deskripsi:"Diskusi kelompok + refleksi individu"}]}],nav:{prev:"s-petunjuk",next:"s-pengantar",nextLabel:"Pengantar"}},{id:"s-pengantar",templateType:"motivasi",sectionLabel:"📖 Pengantar · 5 Menit",sectionColor:"c",blocks:[{type:"motivasi",title:"Dari Kedudukan ke Nilai",hookQuestion:"Jika Pancasila adalah fondasi rumah, maka nilai Pancasila adalah bahan bangunan yang menyusunnya. Tanpa memahami nilainya, kita hanya menghafal simbol — bukan memaknai isi.",visual:{emoji:"💡",bgGradient:["y","bg"]},connections:[{icon:"📖",label:"Pertemuan Lalu",description:"Pancasila adalah dasar negara dan pandangan hidup bangsa. Kita sudah memahami kedudukan Pancasila — tapi apa isi dari Pancasila? Apa nilai yang dikandungnya?",color:"c"},{icon:"💡",label:"Hari Ini",description:"Kita akan menggali makna dan nilai yang terkandung dalam setiap sila Pancasila, serta mengidentifikasi penerapannya dalam kehidupan nyata!",color:"y"}]},{type:"def-box",borderColor:"g",content:"<strong>Nilai Pancasila</strong> adalah prinsip-prinsip moral dan etika yang menjadi pedoman sikap, perilaku, dan tindakan bangsa Indonesia dalam kehidupan berbangsa dan bernegara. Nilai-nilai ini bersifat universal, tetapi dihayati sesuai kepribadian bangsa Indonesia."},{type:"nc-grid",cards:[{icon:"✅",title:"Mengamalkan",body:"Perilaku yang sesuai dengan nilai Pancasila — dilakukan dengan kesadaran",color:"g"},{icon:"⚠️",title:"Belum Mengamalkan",body:"Mengetahui nilai tapi belum menerapkannya dalam tindakan nyata",color:"y"},{icon:"❌",title:"Melanggar",body:"Perilaku yang bertentangan dengan nilai Pancasila",color:"r"}]},{type:"timeline",title:"🔗 Jembatan Antar Sila",steps:[{icon:"⭐",label:"Sila 1 → 2",description:"Ketuhanan mendasari Kemanusiaan — manusia beradab karena bertuhan",color:"y"},{icon:"⛓️",label:"Sila 2 → 3",description:"Kemanusiaan mendasari Persatuan — kita bersatu karena saling menghargai",color:"c"},{icon:"🌳",label:"Sila 3 → 4",description:"Persatuan mendasari Demokrasi — musyawarah hanya bisa jika kita bersatu",color:"g"},{icon:"🐂",label:"Sila 4 → 5",description:"Demokrasi mendasari Keadilan — keputusan bersama harus berpihak pada keadilan",color:"p"}]}],nav:{prev:"s-tp",next:"s-pemantik",nextLabel:"Pemantik"}},{id:"s-pemantik",templateType:"diskusi",sectionLabel:"🔥 Pemantik · 10 Menit",sectionColor:"r",blocks:[{type:"diskusi",title:"🔥 Pertanyaan Pemantik",questions:[{label:"Pertanyaan 1",icon:"🔥",teks:"Bayangkan kamu tinggal di sebuah kampung yang warganya berbeda-beda agama, suku, dan bahasa. Suatu hari muncul konflik kecil karena kesalahpahaman. Menurut kamu, nilai apa dari Pancasila yang paling dibutuhkan untuk menyelesaikannya?",petunjuk:"Diskusikan dengan 2-3 temanmu. Masing-masing berikan 1 nilai Pancasila beserta alasannya!",color:"r"},{label:"Pertanyaan 2",icon:"🔥",teks:"Di media sosial kamu melihat sebuah video yang menampilkan seorang pelajar menolak berdoa bersama karena berbeda keyakinan. Apakah tindakan itu melanggar Pancasila? Sila mana yang dilanggar dan mengapa?",petunjuk:"Tulis pendapatmu sebelum mendiskusikannya bersama teman kelompok!",color:"c"}]}],nav:{prev:"s-pengantar",next:"s-sila1",nextLabel:"Pulau 1: Ketuhanan"}},{id:"s-sila1",templateType:"materi",sectionLabel:"⭐ Pulau 1 · Ketuhanan YME",sectionColor:"c",blocks:[{type:"materi-section",title:"Ketuhanan Yang Maha Esa",subtitle:"⭐ Sila Pertama — Bintang Emas",icon:"⭐",accentColor:"c",bsnpRequired:!0,content:[{type:"ftab",showReadMarker:!0,showProgress:!0,tabs:[{icon:"📌",label:"Penjabaran",content:[{type:"def-box",borderColor:"y",content:"<strong>Nilai Ketuhanan Yang Maha Esa</strong> mengandung keyakinan bahwa bangsa Indonesia adalah bangsa yang bertuhan. Setiap warga negara memeluk agama dan kepercayaan masing-masing, serta menjalankan ajaran agamanya dengan penuh tanggung jawab. Negara menjamin kebebasan setiap warga untuk memeluk agama dan beribadah sesuai keyakinannya.<br/><br/>Nilai Ketuhanan juga mengandung makna bahwa segala tindakan manusia harus berlandaskan nilai-nilai ketuhanan: kejujuran, keadilan, kebaikan, dan kasih sayang. Segala perbuatan harus dapat dipertanggungjawabkan kepada Tuhan Yang Maha Esa."}]},{icon:"💡",label:"Makna",content:[{type:"nc-grid",cards:[{icon:"🕌",title:"Kebebasan Beragama",body:"Setiap warga negara berhak memeluk agama dan kepercayaannya sendiri tanpa paksaan dari pihak manapun",color:"c"},{icon:"🤝",title:"Toleransi Beragama",body:"Menghormati pemeluk agama lain dan tidak memaksakan keyakinan kepada orang lain",color:"g"},{icon:"🕊️",title:"Kerukunan Antarumat",body:"Hidup berdampingan secara damai antar pemeluk agama yang berbeda dalam kehidupan bermasyarakat",color:"y"}]}]},{icon:"✅",label:"Penerapan",content:[{type:"def-box",borderColor:"g",content:"<strong>✅ Perilaku Sesuai Sila ke-1:</strong><br/>• Beribadah sesuai keyakinan masing-masing<br/>• Menghormati teman yang sedang beribadah<br/>• Mengucapkan selamat Hari Raya kepada semua teman<br/>• Tidak memaksakan keyakinan pada orang lain<br/>• Ikut kerja bakti lintas agama<br/><br/><strong>❌ Perilaku Melanggar Sila ke-1:</strong><br/>• Mengejek cara ibadah agama lain<br/>• Menolak berteman karena beda agama<br/>• Merusak tempat ibadah agama lain<br/>• Memaksakan keyakinan pada orang lain<br/>• Membuat olokan terhadap agama tertentu"}]},{icon:"📖",label:"Definisi",content:[{type:"def-box",borderColor:"c",content:"<strong>Toleransi Beragama</strong> — Sikap menghormati dan menghargai pemeluk agama lain, membiarkan mereka menjalankan ibadah sesuai keyakinannya, serta tidak memaksakan agama sendiri kepada orang lain.<br/><br/><strong>Kerukunan Umat Beragama</strong> — Kondisi hidup berdampingan secara damai dan saling membantu antar umat penganut agama yang berbeda-beda dalam satu wilayah.<br/><br/><strong>Kebebasan Beragama</strong> — Hak setiap warga negara untuk memeluk agama dan kepercayaannya, serta menjalankan ibadah sesuai keyakinan tanpa tekanan dari pihak manapun.<br/><br/><strong>Sekularisme</strong> — Paham yang memisahkan urusan agama dari urusan negara. Indonesia BUKAN negara sekuler karena Pancasila menempatkan Ketuhanan sebagai sila pertama."}]},{icon:"✏️",label:"Uraikan",content:[{type:"diskusi",title:"✏️ Uraikan dengan Kata-katamu",questions:[{label:"Uraian",icon:"✏️",teks:"Apa makna nilai Ketuhanan Yang Maha Esa dan mengapa nilai ini menjadi fondasi bagi sila-sila lainnya?",petunjuk:"Tuliskan dengan kata-katamu sendiri…",color:"c"}]}]}]}],takeaways:["Ketuhanan adalah fondasi moral tertinggi bangsa Indonesia","Toleransi beragama adalah konsekuensi dari nilai Ketuhanan","Negara menjamin kebebasan beragama setiap warga"]},{type:"sortir-game",title:"⚔️ Tantangan Pulau 1",kolom:[{id:"sesuai",label:"Sesuai Sila 1",color:"g"},{id:"melanggar",label:"Melanggar Sila 1",color:"r"}],pool:[{id:"s1-a",text:"🕌⛪ Beribadah sesuai keyakinan masing-masing",category:"sesuai"},{id:"s1-b",text:"🎉🤝 Mengucapkan selamat Hari Raya kepada semua teman",category:"sesuai"},{id:"s1-c",text:"🙏✨ Menghormati teman yang sedang berdoa sebelum makan",category:"sesuai"},{id:"s1-d",text:"🗣️❌ Mengejek cara ibadah agama lain",category:"melanggar"},{id:"s1-e",text:"🙅❌ Menolak berteman karena beda agama",category:"melanggar"},{id:"s1-f",text:"💥❌ Merusak tempat ibadah agama lain",category:"melanggar"}]},{type:"diskusi",title:"💬 Jelaskan Alasanmu",questions:[{label:"Alasan",icon:"💬",teks:"Pilih 1 perilaku yang kamu pilih tadi. Mengapa perilaku itu mencerminkan pengamalan Sila ke-1? Jelaskan alasanmu!",petunjuk:"Tuliskan alasanmu di sini…",color:"c"}]}],nav:{prev:"s-pemantik",next:"s-sila2",nextLabel:"Pulau 2: Kemanusiaan"}},{id:"s-sila2",templateType:"materi",sectionLabel:"⛓️ Pulau 2 · Kemanusiaan",sectionColor:"r",blocks:[{type:"materi-section",title:"Kemanusiaan Yang Adil dan Beradab",subtitle:"⛓️ Sila Kedua — Rantai Emas",icon:"⛓️",accentColor:"r",bsnpRequired:!0,content:[{type:"ftab",showReadMarker:!0,showProgress:!0,tabs:[{icon:"📌",label:"Penjabaran",content:[{type:"def-box",borderColor:"y",content:"<strong>Nilai Kemanusiaan Yang Adil dan Beradab</strong> mengandung pengakuan bahwa setiap manusia memiliki kedudukan, hak, dan kewajiban yang sama sebagai makhluk ciptaan Tuhan. Kemanusiaan yang adil menuntut setiap orang diperlakukan secara adil tanpa diskriminasi, sedangkan kemanusiaan yang beradab menghendaki setiap orang bertindak sesuai dengan norma-norma kesopanan dan kesusilaan.<br/><br/>Sila ke-2 menekankan bahwa manusia Indonesia harus memperlakukan sesama manusia dengan penuh kesadaran bahwa semua orang memiliki harkat dan martabat yang sama serta harus dihormati hak-hak asasinya."}]},{icon:"💡",label:"Makna",content:[{type:"nc-grid",cards:[{icon:"⚖️",title:"Kesetaraan Derajat",body:"Setiap manusia memiliki kedudukan dan hak yang sama tanpa membedakan suku, agama, ras, atau status sosial",color:"r"},{icon:"❤️",title:"Tenggang Rasa",body:"Saling menghargai dan menghormati perasaan orang lain, tidak menyakiti hati atau merendahkan martabat sesama",color:"c"},{icon:"🌍",title:"Kemanusiaan Universal",body:"Mengakui kemanusiaan seluruh umat manusia, bukan hanya bangsa Indonesia — memperjuangkan hak asasi manusia di mana pun",color:"g"}]}]},{icon:"✅",label:"Penerapan",content:[{type:"def-box",borderColor:"g",content:"<strong>✅ Perilaku Sesuai Sila ke-2:</strong><br/>• Menjenguk teman yang sakit<br/>• Membantu korban bencana alam<br/>• Membela teman yang di-bully<br/>• Menghargai perbedaan pendapat<br/>• Menolong orang yang terluka di jalan<br/><br/><strong>❌ Perilaku Melanggar Sila ke-2:</strong><br/>• Mengejek penampilan fisik orang<br/>• Menolak duduk dengan penyandang disabilitas<br/>• Menyebarkan gosip untuk menjatuhkan orang<br/>• Melakukan perundungan (bullying)<br/>• Membeda-bedakan teman berdasarkan status orang tua"}]},{icon:"📖",label:"Definisi",content:[{type:"def-box",borderColor:"r",content:"<strong>Hak Asasi Manusia (HAM)</strong> — Hak dasar yang dimiliki setiap manusia sejak lahir, bersifat universal dan tidak dapat dicabut oleh siapapun. Contoh: hak hidup, hak pendidikan, hak berpendapat.<br/><br/><strong>Kewajiban Asasi</strong> — Kewajiban dasar yang harus dipenuhi setiap manusia kepada Tuhan, sesama manusia, dan negara. Hak dan kewajiban saling berkaitan.<br/><br/><strong>Anti-Diskriminasi</strong> — Sikap menolak segala bentuk perlakuan yang membeda-bedakan seseorang berdasarkan suku, agama, ras, gender, atau status sosial.<br/><br/><strong>Empati</strong> — Kemampuan memahami dan merasakan apa yang dirasakan orang lain, sehingga mampu merespons dengan kepedulian dan kasih sayang."}]},{icon:"✏️",label:"Uraikan",content:[{type:"diskusi",title:"✏️ Uraikan dengan Kata-katamu",questions:[{label:"Uraian",icon:"✏️",teks:"Apa makna nilai Kemanusiaan Yang Adil dan Beradab? Mengapa kemanusiaan harus bersifat adil DAN beradab sekaligus?",petunjuk:"Tuliskan dengan kata-katamu sendiri…",color:"r"}]}]}]}],takeaways:["Kemanusiaan mengakui kesetaraan derajat setiap manusia","Adil berarti memperlakukan setiap orang secara setara, beradab berarti bertindak sesuai norma","Hak dan kewajiban asasi manusia saling berkaitan dan tidak dapat dipisahkan"]},{type:"sortir-game",title:"⚔️ Tantangan Pulau 2",kolom:[{id:"sesuai",label:"Sesuai Sila 2",color:"g"},{id:"melanggar",label:"Melanggar Sila 2",color:"r"}],pool:[{id:"s2-a",text:"🏥 Menjenguk teman yang sakit",category:"sesuai"},{id:"s2-b",text:"🌊 Membantu korban banjir",category:"sesuai"},{id:"s2-c",text:"🛡️ Membela teman yang di-bully",category:"sesuai"},{id:"s2-d",text:"😤 Mengejek penampilan fisik orang",category:"melanggar"},{id:"s2-e",text:"🚫 Menolak duduk dengan penyandang disabilitas",category:"melanggar"},{id:"s2-f",text:"🗣️ Menyebarkan gosip untuk menjatuhkan orang",category:"melanggar"}]},{type:"diskusi",title:"💬 Jelaskan Alasanmu",questions:[{label:"Alasan",icon:"💬",teks:"Pilih 1 perilaku yang kamu pilih tadi. Mengapa perilaku itu mencerminkan pengamalan Sila ke-2? Jelaskan alasanmu!",petunjuk:"Tuliskan alasanmu di sini…",color:"r"}]}],nav:{prev:"s-sila1",next:"s-sila3",nextLabel:"Pulau 3: Persatuan"}},{id:"s-sila3",templateType:"materi",sectionLabel:"🌳 Pulau 3 · Persatuan",sectionColor:"g",blocks:[{type:"materi-section",title:"Persatuan Indonesia",subtitle:"🌳 Sila Ketiga — Pohon Beringin",icon:"🌳",accentColor:"g",bsnpRequired:!0,content:[{type:"ftab",showReadMarker:!0,showProgress:!0,tabs:[{icon:"📌",label:"Penjabaran",content:[{type:"def-box",borderColor:"y",content:"<strong>Nilai Persatuan Indonesia</strong> mengandung makna bahwa bangsa Indonesia mengutamakan persatuan, kesatuan, dan kepentingan bersama di atas kepentingan pribadi atau golongan. Persatuan dikembangkan atas dasar Bhinneka Tunggal Ika — mempersatukan berbagai suku, budaya, bahasa, dan agama menjadi satu bangsa Indonesia.<br/><br/>Sila ke-3 menekankan bahwa meskipun Indonesia terdiri dari keragaman, semua komponen bangsa harus bersatu demi kepentingan nasional. Nasionalisme dan cinta tanah air menjadi perekat persatuan bangsa."}]},{icon:"💡",label:"Makna",content:[{type:"nc-grid",cards:[{icon:"🇮🇩",title:"Nasionalisme",body:"Rasa cinta dan bangga terhadap bangsa dan negara Indonesia, mengutamakan kepentingan nasional di atas kepentingan pribadi",color:"g"},{icon:"🌈",title:"Bhinneka Tunggal Ika",body:"Berbeda-beda tetapi tetap satu jua — menjunjung tinggi persatuan dalam keberagaman suku, budaya, bahasa, dan agama",color:"c"},{icon:"🏠",title:"Cinta Tanah Air",body:"Rasa memiliki dan menghargai tanah air Indonesia, termasuk melestarikan budaya dan membeli produk dalam negeri",color:"y"}]}]},{icon:"✅",label:"Penerapan",content:[{type:"def-box",borderColor:"g",content:"<strong>✅ Perilaku Sesuai Sila ke-3:</strong><br/>• Mengikuti upacara bendera dengan khidmat<br/>• Bangga memakai batik dan produk lokal<br/>• Bergotong royong membersihkan lingkungan<br/>• Menghargai teman dari daerah berbeda<br/>• Tidak menyebarkan hoaks yang memecah belah<br/><br/><strong>❌ Perilaku Melanggar Sila ke-3:</strong><br/>• Mengejek logat bicara orang dari daerah lain<br/>• Membuat grup hanya untuk satu suku di sekolah<br/>• Menyebarkan meme yang menghina suku tertentu<br/>• Menolak berteman karena berbeda suku<br/>• Lebih bangga produk asing tanpa alasan yang jelas"}]},{icon:"📖",label:"Definisi",content:[{type:"def-box",borderColor:"g",content:'<strong>Nasionalisme</strong> — Paham atau kesadaran keanggotaan dalam suatu bangsa yang secara potensial atau aktual bersama-sama mencapai, mempertahankan, dan mengabdikan identitas keberadaan bangsa itu.<br/><br/><strong>Bhinneka Tunggal Ika</strong> — Semboyan negara Indonesia yang berarti "Berbeda-beda tetapi tetap satu jua". Menunjukkan bahwa keragaman justru menjadi kekuatan persatuan bangsa.<br/><br/><strong>Integrasi Nasional</strong> — Proses penyatuan berbagai kelompok masyarakat yang berbeda-beda latar belakang budaya, sosial, dan wilayah menjadi satu kesatuan bangsa yang utuh.<br/><br/><strong>Chauvinisme</strong> — Paham yang menganggap bangsa atau kelompok sendiri paling hebat dan merendahkan bangsa/kelompok lain. Bertentangan dengan semangat Bhinneka Tunggal Ika.'}]},{icon:"✏️",label:"Uraikan",content:[{type:"diskusi",title:"✏️ Uraikan dengan Kata-katamu",questions:[{label:"Uraian",icon:"✏️",teks:"Apa makna nilai Persatuan Indonesia dan bagaimana Bhinneka Tunggal Ika menjadi dasar persatuan bangsa kita?",petunjuk:"Tuliskan dengan kata-katamu sendiri…",color:"g"}]}]}]}],takeaways:["Persatuan mengutamakan kepentingan bersama di atas kepentingan pribadi","Bhinneka Tunggal Ika: keragaman menjadi kekuatan, bukan kelemahan","Nasionalisme dan cinta tanah air adalah perekat persatuan bangsa"]},{type:"sortir-game",title:"⚔️ Tantangan Pulau 3",kolom:[{id:"sesuai",label:"Sesuai Sila 3",color:"g"},{id:"melanggar",label:"Melanggar Sila 3",color:"r"}],pool:[{id:"s3-a",text:"🇮🇩 Mengikuti upacara bendera dengan khidmat",category:"sesuai"},{id:"s3-b",text:"👕 Bangga memakai batik dan produk lokal",category:"sesuai"},{id:"s3-c",text:"🧹 Bergotong royong membersihkan lingkungan",category:"sesuai"},{id:"s3-d",text:"😤 Mengejek logat bicara orang dari daerah lain",category:"melanggar"},{id:"s3-e",text:"🚫 Membuat grup hanya untuk satu suku di sekolah",category:"melanggar"},{id:"s3-f",text:"📱 Menyebarkan meme yang menghina suku tertentu",category:"melanggar"}]},{type:"diskusi",title:"💬 Jelaskan Alasanmu",questions:[{label:"Alasan",icon:"💬",teks:"Pilih 1 perilaku yang kamu pilih tadi. Mengapa perilaku itu mencerminkan pengamalan Sila ke-3? Jelaskan alasanmu!",petunjuk:"Tuliskan alasanmu di sini…",color:"g"}]}],nav:{prev:"s-sila2",next:"s-sila4",nextLabel:"Pulau 4: Kerakyatan"}},{id:"s-sila4",templateType:"materi",sectionLabel:"🐂 Pulau 4 · Kerakyatan",sectionColor:"o",blocks:[{type:"materi-section",title:"Kerakyatan yang Dipimpin oleh Hikmat Kebijaksanaan dalam Permusyawaratan/Perwakilan",subtitle:"🐂 Sila Keempat — Kepala Banteng",icon:"🐂",accentColor:"o",bsnpRequired:!0,content:[{type:"ftab",showReadMarker:!0,showProgress:!0,tabs:[{icon:"📌",label:"Penjabaran",content:[{type:"def-box",borderColor:"y",content:"<strong>Nilai Kerakyatan</strong> mengandung makna bahwa kedaulatan berada di tangan rakyat. Setiap keputusan yang menyangkut kepentingan bersama harus diambil melalui musyawarah untuk mufakat. Musyawarah dilakukan dengan akal sehat dan hati nurani, bukan berdasarkan tekanan, kekerasan, atau pemaksaan kehendak.<br/><br/>Sila ke-4 menekankan pentingnya demokrasi Pancasila — demokrasi yang berlandaskan nilai-nilai Pancasila, bukan demokrasi liberal yang semata-mata mengandalkan suara terbanyak. Musyawarah mufakat adalah cara utama, voting hanya digunakan sebagai upaya terakhir jika mufakat tidak tercapai."}]},{icon:"💡",label:"Makna",content:[{type:"nc-grid",cards:[{icon:"🗣️",title:"Musyawarah Mufakat",body:"Pengambilan keputusan bersama melalui diskusi untuk mencapai kesepakatan terbaik, bukan sekadar suara terbanyak",color:"o"},{icon:"🗳️",title:"Demokrasi Pancasila",body:"Demokrasi yang berlandaskan nilai-nilai Pancasila — mengutamakan musyawarah dan kebijaksanaan",color:"c"},{icon:"👥",title:"Kedaulatan Rakyat",body:"Kekuasaan tertinggi berada di tangan rakyat — rakyat berperan aktif dalam setiap pengambilan keputusan",color:"p"}]}]},{icon:"✅",label:"Penerapan",content:[{type:"def-box",borderColor:"g",content:"<strong>✅ Perilaku Sesuai Sila ke-4:</strong><br/>• Bermusyawarah sebelum mengambil keputusan bersama<br/>• Menghargai pendapat yang berbeda<br/>• Menerima hasil musyawarah dengan lapang dada<br/>• Tidak memaksakan kehendak pada orang lain<br/>• Ikut serta dalam pemilihan secara jujur<br/><br/><strong>❌ Perilaku Melanggar Sila ke-4:</strong><br/>• Memaksakan kehendak pada orang lain<br/>• Mengambil keputusan sepihak tanpa musyawarah<br/>• Tidak menghargai pendapat yang berbeda<br/>• Golput tanpa alasan yang jelas<br/>• Menyuap atau menyalahgunakan kekuasaan"}]},{icon:"📖",label:"Definisi",content:[{type:"def-box",borderColor:"o",content:"<strong>Musyawarah</strong> — Proses diskusi dan perundingan bersama untuk mencapai kesepakatan tentang suatu hal yang menyangkut kepentingan bersama.<br/><br/><strong>Mufakat</strong> — Kesepakatan bersama yang dicapai melalui musyawarah. Mufakat lebih diutamakan daripada voting karena mencerminkan kehendak seluruh pihak.<br/><br/><strong>Demokrasi Pancasila</strong> — Sistem demokrasi yang berlandaskan nilai-nilai Pancasila, mengutamakan musyawarah mufakat dan kebijaksanaan dalam permusyawaratan perwakilan.<br/><br/><strong>Golput (Golongan Putih)</strong> — Tidak menggunakan hak suara dalam pemilihan. Bisa bertentangan dengan Sila ke-4 karena tidak menjalankan kewajiban demokratis sebagai warga negara."}]},{icon:"✏️",label:"Uraikan",content:[{type:"diskusi",title:"✏️ Uraikan dengan Kata-katamu",questions:[{label:"Uraian",icon:"✏️",teks:"Apa makna nilai Kerakyatan dan mengapa musyawarah mufakat lebih diutamakan daripada voting?",petunjuk:"Tuliskan dengan kata-katamu sendiri…",color:"o"}]}]}]}],takeaways:["Kedaulatan berada di tangan rakyat — keputusan bersama melalui musyawarah","Musyawarah mufakat lebih diutamakan daripada voting","Demokrasi Pancasila berlandaskan nilai-nilai Pancasila, bukan sekadar suara terbanyak"]},{type:"kuis",title:"⚔️ Tantangan Pulau 4 — Studi Kasus",questions:[{q:"Kelas 7B memilih ketua OSIS. Cara yang paling sesuai dengan Sila ke-4 adalah...",opts:["Menunjuk langsung tanpa pemilihan","Voting setelah presentasi visi dan misi masing-masing kandidat","Memilih berdasarkan siapa yang paling populer","Tidak perlu memilih, biarkan guru yang menentukan"],ans:1,ex:"Voting setelah presentasi visi dan misi adalah cara demokratis yang sesuai Sila ke-4 — rakyat (siswa) memilih secara bebas berdasarkan informasi."},{q:"Pendapat Andi tidak disetujui oleh mayoritas teman dalam musyawarah. Sikap Andi yang sesuai Sila ke-4 adalah...",opts:["Menolak menerima keputusan dan pergi","Menerima dengan lapang dada karena hasil musyawarah","Memaksa teman untuk mengikuti pendapatnya","Mengancam tidak akan ikut kegiatan lagi"],ans:1,ex:"Menerima hasil musyawarah dengan lapang dada menunjukkan kedewasaan berdemokrasi sesuai Sila ke-4 — menghargai keputusan bersama."},{q:"RW ingin membangun taman bermain di lingkungan. Langkah yang sesuai Sila ke-4 adalah...",opts:["Ketua RW memutuskan sendiri","Musyawarah seluruh warga untuk mufakat","Hanya menanyakan pendapat tokoh masyarakat","Menyerahkan keputusan pada pemerintah kota"],ans:1,ex:"Musyawarah seluruh warga sesuai Sila ke-4 — keputusan yang menyangkut kepentingan bersama harus diambil melalui permusyawaratan."},{q:"Saat pemilu, Budi merasa pilihannya tidak bagus. Sikap yang sesuai Sila ke-4 adalah...",opts:["Tidak ikut memilih (golput)","Memilih dengan cermat sesuai hati nurani","Memilih karena ikut-ikutan teman","Mengganggu proses pemilihan"],ans:1,ex:"Memilih dengan cermat sesuai hati nurani adalah kewajiban demokratis sesuai Sila ke-4 — menggunakan hak suara secara bertanggung jawab."}]},{type:"diskusi",title:"💬 Jelaskan Alasanmu",questions:[{label:"Alasan",icon:"💬",teks:"Dari 4 studi kasus tadi, pilih 1 yang paling berkesan. Mengapa kasus itu membuatmu tersentuh dan apa pelajaran yang bisa kamu ambil?",petunjuk:"Tuliskan alasanmu di sini…",color:"o"}]}],nav:{prev:"s-sila3",next:"s-sila5",nextLabel:"Pulau 5: Keadilan"}},{id:"s-sila5",templateType:"materi",sectionLabel:"🌾 Pulau 5 · Keadilan",sectionColor:"y",blocks:[{type:"materi-section",title:"Keadilan Sosial bagi Seluruh Rakyat Indonesia",subtitle:"🌾 Sila Kelima — Padi dan Kapas",icon:"🌾",accentColor:"y",bsnpRequired:!0,content:[{type:"ftab",showReadMarker:!0,showProgress:!0,tabs:[{icon:"📌",label:"Penjabaran",content:[{type:"def-box",borderColor:"y",content:"<strong>Nilai Keadilan Sosial</strong> mengandung makna bahwa setiap warga negara Indonesia berhak mendapatkan perlakuan yang adil dalam segala bidang kehidupan — ekonomi, sosial, budaya, dan politik. Keadilan sosial menuntut pemerataan pembangunan dan kesejahteraan bagi seluruh rakyat, bukan hanya kelompok tertentu.<br/><br/>Sila ke-5 menekankan bahwa kemakmuran harus dirasakan oleh seluruh rakyat Indonesia. Tidak boleh ada kesenjangan sosial yang terlalu besar antara yang kaya dan yang miskin. Setiap orang harus bersikap adil, tidak boros, dan peduli terhadap sesama yang kurang mampu."}]},{icon:"💡",label:"Makna",content:[{type:"nc-grid",cards:[{icon:"⚖️",title:"Keadilan Distributif",body:"Setiap warga negara berhak mendapat bagian yang adil dari hasil pembangunan dan kemakmuran negara",color:"y"},{icon:"🤲",title:"Keadilan Komutatif",body:"Setiap orang harus memperlakukan orang lain secara adil — memberikan apa yang menjadi haknya",color:"c"},{icon:"📜",title:"Keadilan Legal",body:"Setiap warga negara diperlakukan sama oleh hukum tanpa memandang status sosial atau kekayaan",color:"g"}]}]},{icon:"✅",label:"Penerapan",content:[{type:"def-box",borderColor:"g",content:"<strong>✅ Perilaku Sesuai Sila ke-5:</strong><br/>• Rajin menabung uang saku<br/>• Berbagi bekal makanan dengan teman yang tidak membawa<br/>• Menggunakan fasilitas sekolah dengan bertanggung jawab<br/>• Tidak membuang-buang makanan<br/>• Membantu teman yang kurang mampu<br/><br/><strong>❌ Perilaku Melanggar Sila ke-5:</strong><br/>• Pamer barang mahal di media sosial terus-menerus<br/>• Membuang makanan masih baik karena bosan<br/>• Mencontek saat ujian untuk dapat nilai bagus<br/>• Korupsi uang publik<br/>• Membeli barang mewah secara berlebihan sementara orang lain kelaparan"}]},{icon:"📖",label:"Definisi",content:[{type:"def-box",borderColor:"y",content:"<strong>Keadilan Sosial</strong> — Keadilan yang menyangkut pemerataan hak dan kewajiban bagi seluruh warga negara dalam bidang ekonomi, sosial, budaya, dan politik.<br/><br/><strong>Pemerataan</strong> — Upaya pembagian yang seimbang dan adil atas hasil pembangunan dan sumber daya nasional bagi seluruh rakyat Indonesia tanpa diskriminasi.<br/><br/><strong>Ketidakadilan</strong> — Keadaan di mana seseorang atau kelompok tidak mendapatkan haknya secara layak atau diperlakukan tidak sama oleh sistem sosial.<br/><br/><strong>Kesejahteraan</strong> — Kondisi kehidupan yang layak, sejahtera, dan bermartabat bagi seluruh rakyat Indonesia — tujuan utama Sila ke-5."}]},{icon:"✏️",label:"Uraikan",content:[{type:"diskusi",title:"✏️ Uraikan dengan Kata-katamu",questions:[{label:"Uraian",icon:"✏️",teks:"Apa makna nilai Keadilan Sosial bagi Seluruh Rakyat Indonesia dan mengapa keadilan harus dirasakan oleh SEMUA warga negara?",petunjuk:"Tuliskan dengan kata-katamu sendiri…",color:"y"}]}]}]}],takeaways:["Keadilan sosial menuntut pemerataan bagi seluruh rakyat Indonesia","Setiap warga berhak mendapat perlakuan adil dalam segala bidang kehidupan","Kemakmuran harus dirasakan bersama, bukan hanya kelompok tertentu"]},{type:"sortir-game",title:"⚔️ Tantangan Pulau 5",kolom:[{id:"sesuai",label:"Sesuai Sila 5",color:"g"},{id:"melanggar",label:"Melanggar Sila 5",color:"r"}],pool:[{id:"s5-a",text:"💰 Rajin menabung uang saku",category:"sesuai"},{id:"s5-b",text:"🍱 Berbagi bekal makanan dengan teman yang tidak membawa",category:"sesuai"},{id:"s5-c",text:"📚 Menggunakan fasilitas sekolah dengan bertanggung jawab",category:"sesuai"},{id:"s5-d",text:"📱 Pamer barang mahal di media sosial terus-menerus",category:"melanggar"},{id:"s5-e",text:"🗑️ Membuang makanan masih baik karena bosan",category:"melanggar"},{id:"s5-f",text:"📝 Mencontek saat ujian untuk dapat nilai bagus",category:"melanggar"}]},{type:"diskusi",title:"💬 Jelaskan Alasanmu",questions:[{label:"Alasan",icon:"💬",teks:"Pilih 1 perilaku yang kamu pilih tadi. Mengapa perilaku itu mencerminkan pengamalan Sila ke-5? Jelaskan alasanmu!",petunjuk:"Tuliskan alasanmu di sini…",color:"y"}]}],nav:{prev:"s-sila4",next:"s-kuis",nextLabel:"Evaluasi Akhir"}},{id:"s-kuis",templateType:"kuis",sectionLabel:"⛰️ Pendakian Akhir · 15 Menit",sectionColor:"o",blocks:[{type:"kuis",title:"⛰️ Pendakian Akhir — Evaluasi",questions:[{q:"Tindakan berikut yang PALING mencerminkan pengamalan Sila ke-1 Pancasila adalah...",opts:["Membantu teman yang kesulitan mengerjakan PR","Menghormati teman yang sedang berdoa sebelum makan","Mengikuti upacara bendera dengan tertib","Menabung sebagian uang saku setiap hari"],ans:1,ex:"Menghormati teman yang sedang berdoa adalah wujud nyata toleransi beragama sesuai Sila ke-1 Ketuhanan Yang Maha Esa."},{q:"Rina melihat temannya Dinda sedang di-bully oleh sekelompok siswa. Tindakan yang paling sesuai dengan Sila ke-2 adalah...",opts:["Pura-pura tidak melihat","Ikut menonton dan merekam","Segera membela Dinda dan melaporkan ke guru","Menunggu kejadian selesai baru bertindak"],ans:2,ex:"Membela Dinda dan melaporkan ke guru menunjukkan keberanian membela kebenaran dan kemanusiaan sesuai Sila ke-2."},{q:"Bangga menggunakan produk buatan Indonesia merupakan penerapan Sila ke...",opts:["Sila ke-2","Sila ke-3","Sila ke-4","Sila ke-5"],ans:1,ex:"Bangga menggunakan produk lokal menunjukkan cinta tanah air dan nasionalisme sesuai Sila ke-3 Persatuan Indonesia."},{q:"Dalam rapat pemilihan ketua kelas, hasil musyawarah tidak sesuai dengan keinginan Bagas. Sikap yang sesuai Pancasila adalah...",opts:["Tidak mau bersekolah","Menerima hasil dengan lapang dada","Memengaruhi teman untuk menolak","Mengajukan protes keras"],ans:1,ex:"Menerima hasil musyawarah dengan lapang dada adalah wujud demokrasi dan menghargai keputusan bersama sesuai Sila ke-4."},{q:"Perilaku yang PALING mencerminkan Sila ke-5 di lingkungan sekolah adalah...",opts:["Meminjamkan alat tulis kepada teman yang tidak punya","Selalu mendapat nilai ujian terbaik","Memiliki banyak teman dari berbagai daerah","Rajin mengikuti kegiatan ekstrakurikuler"],ans:0,ex:"Meminjamkan alat tulis kepada teman yang tidak punya menunjukkan keadilan sosial dan kepedulian sesuai Sila ke-5."}]}],nav:{prev:"s-sila5",next:"s-hasil",nextLabel:"Lihat Hasil 🏆"}},{id:"s-hasil",templateType:"hasil",sectionLabel:"🏆 Hasil",sectionColor:"g",background:{type:"radial",color1:"g",color2:"bg"},blocks:[{type:"hasil",title:"Misi Penjelajah Pancasila",subtitle:"Pertemuan 2 Selesai! 🎉"}],nav:{prev:"s-kuis",next:"s-refleksi",nextLabel:"Refleksi 📝"}},{id:"s-refleksi",templateType:"refleksi",sectionLabel:"🏕️ Perkemahan · 10 Menit",sectionColor:"p",blocks:[{type:"diskusi",title:"💬 Diskusi Kelompok",questions:[{label:"Sila 1",icon:"⭐",teks:"Di media sosial, kamu menemukan komentar yang menghina agama tertentu. Langkah apa yang kamu ambil sebagai pelajar Pancasila?",petunjuk:"Diskusikan 3 langkah konkret!",color:"c"},{label:"Sila 2",icon:"⛓️",teks:"Kamu melihat seseorang jatuh dan terluka di jalan. Di sekitarmu banyak orang yang malah langsung mengeluarkan HP untuk merekam. Apa yang akan kamu lakukan?",petunjuk:"Satu anggota ceritakan pengalamannya!",color:"r"},{label:"Sila 3",icon:"🌳",teks:"Bagaimana cara kita menjaga persatuan bangsa Indonesia di era media sosial yang penuh dengan konten provokatif dan berita hoax?",petunjuk:"Buat 5 tips nyata sebagai pelajar!",color:"g"},{label:"Sila 4",icon:"🐂",teks:"Berikan contoh situasi di sekolah atau keluarga di mana musyawarah mufakat GAGAL diterapkan. Apa yang terjadi? Bagaimana seharusnya?",petunjuk:"Setiap anggota ceritakan 1 pengalaman!",color:"o"},{label:"Sila 5",icon:"🌾",teks:"Apakah semua siswa di sekolahmu mendapat perlakuan yang sama adilnya? Jika ada ketidakadilan, contoh apa dan bagaimana mengatasinya?",petunjuk:"Diskusikan dengan jujur!",color:"y"}]},{type:"flashcard-set",cards:[{q:"Apa nilai utama yang terkandung dalam Sila ke-1?",a:"Nilai Ketuhanan: Toleransi beragama, kebebasan beribadah, dan menghormati perbedaan keyakinan tanpa diskriminasi."},{q:"Apa perbedaan HAM dan Kewajiban Asasi?",a:"HAM = Hak dasar yang dimiliki sejak lahir. Kewajiban Asasi = Kewajiban dasar yang harus dipenuhi setiap manusia kepada Tuhan, sesama, dan negara."},{q:"Apa arti semboyan 'Bhinneka Tunggal Ika'?",a:"'Berbeda-beda tetapi tetap satu jua' — menjunjung tinggi persatuan dalam keberagaman suku, budaya, bahasa, dan agama Indonesia."},{q:"Apa perbedaan Musyawarah dan Voting?",a:"Musyawarah = Diskusi bersama mencari mufakat terbaik. Voting = Pengambilan suara terbanyak sebagai alternatif TERAKHIR jika mufakat tidak tercapai."},{q:"Berikan 3 contoh pelanggaran Sila ke-5 di kehidupan nyata!",a:"1) Korupsi uang publik, 2) Pamer kekayaan berlebihan (flexing), 3) Membuang-buang makanan dan sumber daya tanpa kepedulian."},{q:"Apa yang dimaksud 'Kerukunan Umat Beragama'?",a:"Kondisi hidup berdampingan secara damai dan saling membantu antar umat penganut agama yang berbeda-beda dalam satu wilayah."},{q:"Mengapa bullying bertentangan dengan Sila ke-2?",a:"Karena Sila ke-2 mengajarkan kemanusiaan yang beradab, kesetaraan derajat, dan tenggang rasa. Bullying merendahkan martabat manusia lain."},{q:"Apa contoh nasionalisme di era digital?",a:"Tidak menyebarkan hoax yang memecah belah, mempromosikan produk lokal, menggunakan Bahasa Indonesia dengan baik di platform digital."},{q:"Mengapa golput bisa bertentangan dengan Sila ke-4?",a:"Karena Sila ke-4 mengajarkan keikutsertaan aktif dalam permusyawaratan/perwakilan. Golput tanpa alasan berarti tidak menjalankan kewajiban demokratis sebagai warga negara."}]},{type:"refleksi",title:"📝 Refleksi Individu",intro:"Jawaban jujurmu lebih berharga dari jawaban yang sempurna.",questions:[{teks:"Nilai Pancasila apa yang paling berkesan bagimu hari ini? Mengapa nilai itu terasa relevan dengan kehidupanmu?",petunjuk:"Contoh: Nilai toleransi (Sila 1) paling berkesan karena…",warna:"y",icon:"💡"},{teks:"Tuliskan 2 tindakan konkret yang AKAN kamu mulai lakukan besok untuk mengamalkan nilai Pancasila!",petunjuk:"1) Mulai besok saya akan… 2) Minggu ini saya akan…",warna:"c",icon:"🎯"},{teks:"Apa hal tentang Pancasila yang masih membuatmu penasaran atau ingin kamu pelajari lebih lanjut?",petunjuk:"Saya masih penasaran tentang…",warna:"g",icon:"❓"}],penugasan:{judul:"📌 Penugasan: Portofolio Pancasila",isi:"Selama 1 minggu, catat minimal 3 tindakanmu yang mencerminkan nilai Pancasila. Bisa di rumah, sekolah, atau masyarakat. Tuliskan sila mana yang tercermin.",contoh:"Contoh: Senin — Membantu ibu berbelanja di pasar (Sila 2: Kemanusiaan & Sila 5: Keadilan)"}}],nav:{prev:"s-hasil",next:"s-penutup",nextLabel:"Penutup"}},{id:"s-penutup",templateType:"penutup",sectionLabel:"📜 Penutup",sectionColor:"g",blocks:[{type:"penutup",title:"Sampai Jumpa, Penjelajah!",subtitle:"Pertemuan 3: Studi Kasus & Komitmen Pancasila",preview:[{icon:"📋",judul:"Studi Kasus",isi:"Mengevaluasi kasus nyata pengamalan/pelanggaran Pancasila",warna:"y"},{icon:"🤝",judul:"Komitmen",isi:"Merancang tindakan nyata pengamalan Pancasila",warna:"c"}],nextPertemuan:{judul:"Pertemuan 3: Studi Kasus & Komitmen Pancasila",deskripsi:"Akan membahas lebih dalam tentang penerapan dan pelanggaran nilai Pancasila melalui studi kasus nyata, serta merancang komitmen tindakan nyata pengamalan Pancasila.",items:[{icon:"📋",judul:"Studi Kasus",isi:"Evaluasi kasus nyata terkait Pancasila",warna:"y"},{icon:"🤝",judul:"Komitmen",isi:"Merancang tindakan nyata pengamalan",warna:"c"}]}}],nav:{prev:"s-refleksi"}}]};a.s(["MISI_PENJELAJAH_PANCASILA_LESSON",0,b])}];

